from __future__ import annotations


def render_kuzu_risk_page() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuzu 关联风险扩散</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e5e7eb;background:#0b1220}*{box-sizing:border-box}body{margin:0}.bar{padding:14px 22px;border-bottom:1px solid #263246;background:#111827;display:flex;gap:14px;align-items:center}.back{color:#93c5fd;text-decoration:none;border:1px solid #2563eb;border-radius:4px;padding:5px 9px}.brand{font-size:18px;font-weight:700}.hint{font-size:12px;color:#aeb7c2}.layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;min-height:calc(100vh - 59px)}.stage{padding:18px}.tools{display:flex;gap:12px;align-items:center;margin-bottom:12px;flex-wrap:wrap}.tools input{width:72px;background:#111827;color:#fff;border:1px solid #475569;border-radius:4px;padding:7px}.tools input[type=checkbox]{width:auto;padding:0;accent-color:#2563eb}.tools button{background:#2563eb;color:#fff;border:0;border-radius:4px;padding:8px 12px;cursor:pointer}.legend{display:flex;gap:10px;font-size:12px;color:#cbd5e1}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.board{height:calc(100vh - 145px);min-height:560px;border:1px solid #334155;border-radius:8px;background:#101826;overflow:hidden}.board canvas{width:100%;height:100%;display:block;touch-action:none;cursor:grab}.board canvas:active{cursor:grabbing}.side{padding:22px;background:#111827;border-left:1px solid #263246}.side h1{font-size:20px;margin:4px 0 16px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;border-top:1px solid #334155;border-bottom:1px solid #334155;padding:12px 0}.metric b{display:block;font-size:20px}.muted{font-size:12px;color:#94a3b8}.detail{line-height:1.6;font-size:14px;margin-top:18px}.detail ul{padding-left:18px}.error{color:#fca5a5}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{border-left:0;border-top:1px solid #263246}.board{height:560px}}</style></head><body><header class="bar"><a class="back" id="back" href="/">← 返回账户</a><span class="brand">Kuzu 关联风险扩散</span><span class="hint">滚轮缩放，拖拽平移 · 超过查询预算会返回部分图谱</span><span class="hint" id="status">读取中…</span></header><main class="layout"><section class="stage"><div class="tools"><label>扩散阈值 <input id="threshold" type="number" min="1" max="100" value="20"></label><label title="全平台同步开平仓核验会明显增加耗时"><input id="includeToxic" type="checkbox"> 包含 Toxic 同步订单（较慢）</label><button id="reload">重新计算</button><span class="legend"><span><i class="dot" style="background:#ff2638"></i>问题账户</span><span><i class="dot" style="background:#f97316"></i>高分关联</span><span><i class="dot" style="background:#fb923c"></i>低分关联</span><span><i class="dot" style="background:#22c55e"></i>停止扩散</span></span></div><div class="board"><canvas id="graph" aria-label="Kuzu 关联风险图"></canvas></div></section><aside class="side"><div class="muted">问题账户</div><h1 id="account">-</h1><div class="metrics"><div class="metric"><span class="muted">节点</span><b id="nodes">-</b></div><div class="metric"><span class="muted">关系</span><b id="edges">-</b></div></div><div class="detail" id="detail">选择节点，查看该账户为何被识别及扩散分。</div></aside></main><script>
const canvas=document.getElementById('graph'),ctx=canvas.getContext('2d'),threshold=document.getElementById('threshold'),status=document.getElementById('status'),detail=document.getElementById('detail');let data=null,positions=new Map(),view={scale:1,x:0,y:0},drag=null;
function fit(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);draw()}window.addEventListener('resize',fit);
function combineEdges(edges){const groups=new Map();for(const edge of edges){const key=[edge.source,edge.target].sort().join('|'),group=groups.get(key)||{source:edge.source,target:edge.target,relations:[],strength:0};group.relations.push(edge);group.strength=Math.max(group.strength,Number(edge.strength||0));groups.set(key,group)}return [...groups.values()].map(group=>({...group,relationLabel:[...new Set(group.relations.map(edge=>edge.typeLabel||edge.label||edge.type))].join(' + ')}))}
function nodeColor(node){if(node.isSubject)return '#ff2638';if(!node.expandable)return '#22c55e';const score=Math.max(0,Math.min(100,Number(node.score||0))),light=68-score*.28;return `hsl(16 92% ${light}%)`}
function layout(){const r=canvas.getBoundingClientRect(),center={x:r.width/2,y:r.height/2},edges=combineEdges(data.relationships),nodes=data.entities;positions=new Map();nodes.forEach((node,index)=>{if(node.isSubject){positions.set(node.id,{...center});return}const angle=(index*2.3999632297)%6.28318,radius=390+(index%7)*145;positions.set(node.id,{x:center.x+Math.cos(angle)*radius,y:center.y+Math.sin(angle)*radius})});for(let step=0;step<460;step++){const delta=new Map(nodes.map(node=>[node.id,{x:0,y:0}]));for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=positions.get(nodes[i].id),b=positions.get(nodes[j].id),dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy)),push=Math.max(0,340-d)*.22;delta.get(nodes[i].id).x-=dx/d*push;delta.get(nodes[i].id).y-=dy/d*push;delta.get(nodes[j].id).x+=dx/d*push;delta.get(nodes[j].id).y+=dy/d*push}for(const edge of edges){const a=positions.get(edge.source),b=positions.get(edge.target),dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy)),desired=540-edge.strength*155,pull=(d-desired)*.016;delta.get(edge.source).x+=dx/d*pull;delta.get(edge.source).y+=dy/d*pull;delta.get(edge.target).x-=dx/d*pull;delta.get(edge.target).y-=dy/d*pull}for(const node of nodes){if(node.isSubject)continue;const p=positions.get(node.id),d=delta.get(node.id);p.x+=d.x;p.y+=d.y}}const xs=[...positions.values()].map(p=>p.x),ys=[...positions.values()].map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scale=Math.min(.85,Math.max(.25,Math.min((r.width-120)/Math.max(1,maxX-minX),(r.height-120)/Math.max(1,maxY-minY))));view={scale,x:center.x-(minX+maxX)/2*scale,y:center.y-(minY+maxY)/2*scale}}
function draw(){if(!data)return;const r=canvas.getBoundingClientRect(),edges=combineEdges(data.relationships);ctx.fillStyle='#101826';ctx.fillRect(0,0,r.width,r.height);ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);for(const edge of edges){const a=positions.get(edge.source),b=positions.get(edge.target);if(!a||!b)continue;ctx.strokeStyle=edge.strength>=.8?'#60a5fa':'#64748b';ctx.globalAlpha=.8;ctx.lineWidth=1.2+edge.strength*2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(view.scale>=.72){const x=(a.x+b.x)/2,y=(a.y+b.y)/2,label=edge.relationLabel.slice(0,34);ctx.globalAlpha=.96;ctx.font='11px Microsoft YaHei';const width=ctx.measureText(label).width+12;ctx.fillStyle='#17283e';ctx.fillRect(x-width/2,y-9,width,18);ctx.fillStyle='#dbeafe';ctx.textAlign='center';ctx.fillText(label,x,y+4)}}ctx.globalAlpha=1;for(const n of data.entities){const p=positions.get(n.id),radius=n.isSubject?30:21;ctx.fillStyle=nodeColor(n);ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=n.isSubject?4:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=(n.isSubject?'700 ':'')+'12px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(n.label,p.x,p.y+4);ctx.fillStyle='#cbd5e1';ctx.font='10px Microsoft YaHei';ctx.fillText(n.score.toFixed(1),p.x,p.y+38)}ctx.restore()}
function show(n){detail.replaceChildren();const h=document.createElement('h2');h.textContent=n.label;detail.append(h);for(const text of ['调查传播分：'+n.score.toFixed(2),'层级：'+n.riskLevel,'距问题账户：'+(n.hops||0)+' 跳',n.expandable?'该节点继续扩散':'该节点仅保留为线索，未继续扩散']){const p=document.createElement('p');p.textContent=text;detail.append(p)}if(n.scoreLedger.length){const ul=document.createElement('ul');for(const x of n.scoreLedger){const li=document.createElement('li');li.textContent=x.label+'：'+x.contribution.toFixed(2)+'（'+x.evidence.join('；')+'）';ul.append(li)}detail.append(ul)}}
function worldPoint(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left-view.x)/view.scale,y:(ev.clientY-r.top-view.y)/view.scale}}canvas.addEventListener('wheel',ev=>{ev.preventDefault();const r=canvas.getBoundingClientRect(),before=worldPoint(ev),factor=ev.deltaY<0?1.12:1/1.12,next=Math.max(.28,Math.min(3,view.scale*factor));view.scale=next;view.x=ev.clientX-r.left-before.x*next;view.y=ev.clientY-r.top-before.y*next;draw()},{passive:false});canvas.addEventListener('pointerdown',ev=>{drag={x:ev.clientX,y:ev.clientY,viewX:view.x,viewY:view.y};canvas.setPointerCapture(ev.pointerId)});canvas.addEventListener('pointermove',ev=>{if(!drag)return;view.x=drag.viewX+ev.clientX-drag.x;view.y=drag.viewY+ev.clientY-drag.y;draw()});canvas.addEventListener('pointerup',()=>{drag=null});canvas.addEventListener('click',ev=>{if(!data)return;const point=worldPoint(ev);for(const n of data.entities){const p=positions.get(n.id);if(Math.hypot(point.x-p.x,point.y-p.y)<30){show(n);return}}});
const params=new URLSearchParams(location.search),target=params.get('account')||'',includeToxic=document.getElementById('includeToxic');let requestController=null;if(target){document.getElementById('back').href='/account/'+encodeURIComponent(target)+'?'+params.toString();}function apiUrl(value){if(!target)return '/api/kuzu-risk/graph?threshold='+value;const query=new URLSearchParams();for(const key of ['platform','server','symbol'])if(params.get(key))query.set(key,params.get(key));query.set('threshold',String(value));if(includeToxic.checked)query.set('include_toxic','true');return '/api/accounts/by-login/'+encodeURIComponent(target)+'/relationship-network?'+query.toString();}async function load(){if(requestController)requestController.abort();requestController=new AbortController();const controller=requestController,value=Math.max(1,Math.min(100,Number(threshold.value)||20));threshold.value=value;status.textContent=includeToxic.checked?'读取关系与 Toxic 同步订单中…':'读取关系并评分中…';const timeout=window.setTimeout(()=>controller.abort(),45000);try{const res=await fetch(apiUrl(value),{cache:'no-store',signal:controller.signal});if(!res.ok)throw new Error();data=await res.json();document.getElementById('account').textContent='账户 '+data.account;document.getElementById('nodes').textContent=data.summary.entityCount;document.getElementById('edges').textContent=data.summary.relationshipCount;status.textContent='规则 '+data.summary.ruleVersion+(data.queryBudgetExhausted?' · 查询预算已到，已返回部分图谱':data.truncated?' · 已触发安全上限':' · 完成');layout();fit()}catch(error){if(error.name==='AbortError'){status.textContent='查询超过 45 秒，已停止等待；请提高阈值或取消 Toxic 后重试。';detail.textContent='服务器会在自己的查询预算结束后释放本次只读任务。';}else{status.textContent='图谱读取失败';detail.textContent='请检查账户路由或 Kuzu 本机运行状态。';}}finally{window.clearTimeout(timeout);if(requestController===controller)requestController=null;}}document.getElementById('reload').addEventListener('click',load);load();
</script></body></html>"""
